class User {

    String id;
    String name;
    int age;
    String email;

    User() {
    }

    User(String id) {
        this.id = id;
    }

    User(String id, String name) {
        this.id = id;
        this.name = name;
    }

    User(String id, String name, int age, String email) {
        this.id = id;
        this.name = name;
        this.age = age;
        this.email = email;
    }

    void printDetails() {
        System.out.println(id + " " + name + " " + age + " " + email);
    }
}

public class Main {

    public static void main(String[] args) {

        User u1 = new User("U101");

        User u2 =
            new User("U102", "Ravi");

        User u3 =
            new User("U103", "Anu", 22, "anu@gmail.com");

        u1.printDetails();
        u2.printDetails();
        u3.printDetails();
    }
}

